package com.oracle.banking.branch.dto;import com.oracle.banking.branch.entity.Branch;public final class BranchDtos{private BranchDtos(){}public record Summary(String branchId,String branchName,String ifsc,String city){public static Summary from(Branch b){return new Summary(b.getBranchId(),b.getBranchName(),b.getIfsc(),b.getCity());}}public record Response(String branchId,String branchName,String ifsc,String city,String state){public static Response from(Branch b){return new Response(b.getBranchId(),b.getBranchName(),b.getIfsc(),b.getCity(),b.getState());}}}
